"""Claude Code profile wiring: the `claude-*` aliases in ~/.zshrc.profile, a PATH
wrapper that applies the machine's profile to every `claude` invocation, the
systemd session PATH ordering, and the burst config dir that shares everything
but credentials with ~/.claude."""
from __future__ import annotations

from pathlib import Path

from dotfiles_setup.tooling import Tooling, dry_run_all

# Auth lives here: the live ~/.claude.json and these two entries must never reach the burst profile.
BURST_EXCLUDED = frozenset({".credentials.json", "backups"})
WRAPPER_TEMPLATE = """#!/bin/sh
# Generated by setup.sh (configure_claude_profile) — do not edit.
# Applies the {preset} profile to every PATH invocation of claude, not just
# the interactive zsh sessions that read the ~/.zshrc.profile aliases.
self_dir=$(CDPATH= cd -- "$(dirname -- "$0")" && pwd -P)
real=""
IFS=:
for dir in $PATH; do
    [ -n "$dir" ] || dir=.
    resolved=$(CDPATH= cd -- "$dir" 2>/dev/null && pwd -P) || continue
    [ "$resolved" != "$self_dir" ] || continue
    if [ -x "$resolved/claude" ]; then
        real="$resolved/claude"
        break
    fi
done
unset IFS

if [ -z "$real" ]; then
    echo "claude: no claude binary found on PATH beyond the wrapper at $0" >&2
    exit 127
fi

exec "$real" --settings "{active}" "$@"
"""


def _settings(profile_dir: Path, name: str) -> Path:
    return profile_dir / f"claude_{name}.json"


def _profile_kind(preset_name: str) -> str:
    return preset_name if preset_name in ("work", "homelab") else "personal"


def _burst_entries(claude_home: Path) -> list[Path]:
    if not claude_home.is_dir():
        return []
    return sorted(e for e in claude_home.iterdir() if e.name not in BURST_EXCLUDED)


def _link_burst_dir(burst_dir: Path, claude_home: Path) -> None:
    burst_dir.mkdir(parents=True, exist_ok=True)
    for entry in _burst_entries(claude_home):
        link = burst_dir / entry.name
        if link.is_symlink() or link.is_file():
            link.unlink()
        if not link.exists():
            link.symlink_to(entry)


def _aliases(profile_dir: Path, burst_dir: Path, kind: str) -> str:
    def alias(name: str, profile: str) -> str:
        return f"alias {name}='claude-tmux {profile} claude --settings \"{_settings(profile_dir, profile)}\"'"

    burst = _settings(profile_dir, "burst")
    lines = [
        "# --- Claude Code profiles (generated by setup.sh, do not edit) ---",
        alias("claude-work", "work"),
        alias("claude-personal", "personal"),
        alias("claude-homelab", "homelab"),
        f"alias claude-burst='claude-tmux burst env CLAUDE_CONFIG_DIR=\"{burst_dir}\" claude --settings \"{burst}\"'",
        alias("claude", kind),
        "# --- End Claude Code profile ---",
    ]
    return "\n".join(lines) + "\n"


def configure_claude_profile(t: Tooling, preset_name: str, profile_dir: Path) -> None:
    t.logger.step("Step 7b: Configuring Claude Code profiles...")
    home = t.home
    target, wrapper = home / ".zshrc.profile", home / "bin/claude"
    # Must sort after /usr/lib/environment.d/99-environment.conf, which sets an absolute PATH: the last file wins.
    env_file = home / ".config/environment.d/zz-claude-profile.conf"
    if dry_run_all(
        t, f"Would write Claude work/personal/burst aliases to {target}",
        f"Would write Claude PATH wrapper to {wrapper}",
        f"Would write session PATH ordering to {env_file}",
    ):
        return
    kind = _profile_kind(preset_name)
    burst_dir = home / ".claude-burst"
    _link_burst_dir(burst_dir, home / ".claude")
    target.write_text(_aliases(profile_dir, burst_dir, kind))
    t.logger.success(f"Claude profile aliases written to {target}.")
    wrapper.parent.mkdir(parents=True, exist_ok=True)
    wrapper.write_text(WRAPPER_TEMPLATE.format(preset=preset_name, active=_settings(profile_dir, kind)))
    wrapper.chmod(0o755)
    t.logger.success(f"Claude PATH wrapper written to {wrapper} ({preset_name} profile).")
    env_file.parent.mkdir(parents=True, exist_ok=True)
    # The systemd user manager's PATH carries neither dir, so GUI/IDE-launched apps need both: wrapper first.
    env_file.write_text(
        "# Generated by setup.sh (configure_claude_profile) — do not edit.\n"
        f"PATH={wrapper.parent}:{home}/.local/bin:${{PATH}}\n"
    )
    t.logger.success(f"Session PATH ordering written to {env_file}.")
    t.logger.warn(f"Log out and back in for {env_file} to reach GUI/IDE-launched apps.")
